import json,statistics,math
w=Path(__file__).resolve().parent;c=w/'confirmation'
pilot=json.loads((w/'summary.json').read_text());protocol=json.loads((c/'protocol.json').read_text());n=protocol['pairs'];assert n==64
categories={'build':['build_ik_all_sec','build_ik_content_sec','build_beng_en_sec'],'tokenize':['tokenize_ik_avg_ms','tokenize_beng_avg_ms'],'query':['query_cn_avg_ms','query_beng_avg_ms','query_mixed_avg_ms','query_limit_avg_ms']}
params={'rows':20000,'batch':500,'rounds':3000,'query_rounds':200,'samples':3,'warmup':30,'skip_load':0}
hits={'query_cn_hits':8001,'query_beng_hits':11000,'query_mixed_hits':7332,'query_limit_hits':20}
def read(label):
 text=(c/(label+'.report')).read_text();data={}
 for line in text.splitlines():
  if ':' in line:
   k,v=line.split(':',1)
   try:data[k.strip()]=float(v.strip())
   except ValueError:pass
 assert (c/(label+'.status')).read_text()=='0'
 for k,v in (params|hits).items():assert data[k]==v,(label,k,data[k],v)
 return {'label':label,'metrics':data,'raw_report':text,'resources':json.loads((c/(label+'.resources.json')).read_text())}
pairs=[]
for i in range(1,n+1):
 before=read(f'small-merge-before-{i}');after=read(f'small-merge-after-{i}')
 gain={cat:statistics.mean(1-after['metrics'][k]/before['metrics'][k] for k in keys) for cat,keys in categories.items()}
 pairs.append({'pair':i,'phase':'confirmation','before':before,'after':after,'category_improvements':gain,'overall_improvement':statistics.mean(gain.values())})
def summarize(pairs,critical):
 metrics={};cats={}
 for cat,keys in categories.items():
  for k in keys:
   b=statistics.mean(p['before']['metrics'][k] for p in pairs);a=statistics.mean(p['after']['metrics'][k] for p in pairs)
   metrics[k]={'reference':b,'candidate':a,'improvement':(b-a)/b}
  cats[cat]=statistics.mean(metrics[k]['improvement'] for k in keys)
 x=[p['overall_improvement'] for p in pairs];mean=statistics.mean(x);margin=critical*statistics.stdev(x)/math.sqrt(len(x))
 return {'metric_means':metrics,'category_improvements':cats,'overall_improvement':statistics.mean(cats.values()),'paired_mean':mean,'paired_standard_deviation':statistics.stdev(x),'paired_95_percent_t_interval':[mean-margin,mean+margin],'positive_pairs':sum(v>0 for v in x),'pairs':pairs,'accepted':statistics.mean(cats.values())>0 and mean-margin>0}
confirm=summarize(pairs,1.998340542520741)
confirm['protocol']=protocol;confirm['preconditioning']=[read('precondition-before'),read('precondition-after')]
confirm['blocks']=[{'pairs':list(range(i+1,i+9)),'paired_mean':statistics.mean(p['overall_improvement'] for p in pairs[i:i+8])} for i in range(0,n,8)]
(c/'summary.json').write_text(json.dumps(confirm,indent=2))
combined=summarize([dict(p,phase='pilot') for p in pilot['pairs']]+pairs,1.990450210230128)
result={'reference_commit':pilot['reference_commit'],'binary_metadata':pilot['binary_metadata'],'source_patch':pilot['source_patch'],'validation':pilot['validation'],'public_tests':pilot['public_tests'],'complete_differential_results':678,'pilot':pilot,'confirmation':confirm,'combined':combined,'accepted':confirm['accepted'] and combined['accepted']}
assert not list(c.glob('instance-*'))
(w/'confirmation-summary.json').write_text(json.dumps(result,indent=2))
for name,d in [('pilot',pilot),('confirmation',confirm),('combined',combined)]:
 print(name,json.dumps({k:v for k,v in d.items() if k in ['category_improvements','overall_improvement','paired_mean','paired_95_percent_t_interval','positive_pairs','accepted']},indent=2))
print('FINAL ACCEPTANCE',result['accepted'])
